let activeRatingRecipe=null;
window.submitRating=rating=>{
 const r=RECIPE_LIBRARY.find(x=>x.id===activeRatingRecipe);
 const selectedFeedback=[...document.querySelectorAll(".quick-feedback button.active")].map(b=>b.dataset.feedback);
 const entry={
   recipeId:r.id,
   date:new Date().toISOString(),
   rating,
   notes:ratingNotes.value.trim(),
   context:{mood:selectedMood,occasion:selectedOccasion,strength:selectedStrength},
   serveGuests:serveGuests.checked,
   feedback:selectedFeedback
 };
 history.push(entry);
 detailedFeedback.push(entry);
 if(rating==="house-favourite"&&!favourites.includes(r.id))favourites.push(r.id);
 if(rating==="not-for-me")favourites=favourites.filter(x=>x!==r.id);

 const deltas={
  "too-sweet":{"sweet":-3,"rich":-1},
  "too-bitter":{"bitter":-3},
  "too-herbal":{"herbal":-3},
  "too-strong":{"spirit-forward":-3},
  "loved-citrus":{"citrusy":3,"bright":1},
  "loved-floral":{"floral":3},
  "loved-richness":{"rich":3},
  "serve-guests":{"social":2,"elegant":1}
 };
 selectedFeedback.forEach(code=>Object.entries(deltas[code]||{}).forEach(([tag,val])=>taste[tag]=(taste[tag]||0)+val));
 if(serveGuests.checked){taste.social=(taste.social||0)+1}
 const note=(ratingNotes.value||"").toLowerCase();
 const noteRules=[
  ["too sweet","sweet",-2],["too bitter","bitter",-2],["too herbal","herbal",-2],["too strong","spirit-forward",-2],
  ["loved the citrus","citrusy",2],["loved citrus","citrusy",2],["loved the floral","floral",2],
  ["loved the richness","rich",2],["needed more body","rich",1]
 ];
 noteRules.forEach(([phrase,tag,val])=>{if(note.includes(phrase))taste[tag]=(taste[tag]||0)+val});
 r.tags.forEach(tag=>{if(rating==="house-favourite")taste[tag]=(taste[tag]||0)+1.2;if(rating==="not-for-me")taste[tag]=(taste[tag]||0)-1.2});
 ratingNotes.value="";serveGuests.checked=false;document.querySelectorAll(".quick-feedback button").forEach(b=>b.classList.remove("active"));
 ratingDialog.close();save();getRecommendations()
};
turnTideBtn.onclick=()=>getRecommendations(true);surpriseBtn.onclick=()=>{selectedMood="adventurous";selectedOccasion="music";renderRecommendationControls();getRecommendations(true)};
document.querySelectorAll(".quick-feedback button").forEach(btn=>btn.addEventListener("click",()=>btn.classList.toggle("active")));

const TASTE_DIMENSIONS=["citrusy","floral","herbal","bitter","sweet","rich","spirit-forward","smoky"];
function tasteValue(tag){return Math.max(-10,Math.min(10,Math.round((taste[tag]||0)+(manualPreferences[tag]||0))))}
function confidenceScore(){
 const count=history.length;
 const detail=detailedFeedback.filter(x=>(x.feedback||[]).length||x.notes||x.serveGuests).length;
 return Math.min(100,Math.round(count*8+detail*3));
}
function preferenceDescription(){
 const ranked=TASTE_DIMENSIONS.map(tag=>({tag,value:tasteValue(tag)})).sort((a,b)=>b.value-a.value);
 const liked=ranked.filter(x=>x.value>=2).slice(0,3).map(x=>titleCase(x.tag));
 const avoided=ranked.filter(x=>x.value<=-2).slice(-3).reverse().map(x=>titleCase(x.tag));
 if(!history.length)return "Rate a few cocktails and the app will start building a useful palate profile.";
 let text=liked.length?`You appear to favour ${liked.join(", ")} cocktails.`:"Your positive preferences are still emerging.";
 if(avoided.length)text+=` You tend to avoid ${avoided.join(", ")} profiles.`;
 return text
}
function nextTasteExperiment(){
 const available=availableRecipes().filter(r=>!history.some(h=>h.recipeId===r.id));
 if(!available.length)return null;
 const underexplored=TASTE_DIMENSIONS.map(tag=>({tag,count:history.filter(h=>RECIPE_LIBRARY.find(r=>r.id===h.recipeId)?.tags.includes(tag)).length})).sort((a,b)=>a.count-b.count)[0];
 return available.find(r=>r.tags.includes(underexplored.tag))||available.sort((a,b)=>scoreRecipe(b)-scoreRecipe(a))[0]
}
function renderPreferenceSliders(){
 preferenceSliders.innerHTML=TASTE_DIMENSIONS.map(tag=>`<div class="preference-row"><label>${titleCase(tag)}</label><input type="range" min="-5" max="5" step="1" value="${manualPreferences[tag]||0}" oninput="setManualPreference('${tag}',this.value)"><span class="preference-value">${manualPreferences[tag]||0}</span></div>`).join("")
}
window.setManualPreference=(tag,val)=>{manualPreferences[tag]=Number(val);localStorage.setItem(MANUAL_PREF_KEY,JSON.stringify(manualPreferences));renderTaste();getRecommendations()};

function renderTaste(){
 const confidence=confidenceScore();
 tasteConfidence.textContent=`${confidence}%`;
 tasteConfidenceLabel.textContent=confidence<25?"Early learning":confidence<60?"Developing profile":confidence<85?"Reliable profile":"High confidence";
 ratedCount.textContent=history.length;
 favouriteCount.textContent=favourites.length;

 const ranked=Object.entries(taste).sort((a,b)=>b[1]-a[1]);
 tasteProfile.innerHTML=ranked.length?ranked.slice(0,12).map(([tag,val])=>`<div class="taste-chip ${val<0?"negative":""}">${titleCase(tag)} <strong>${val>0?"+":""}${Math.round(val)}</strong></div>`).join(""):`<p class="helper">Make and rate a few cocktails to teach the app your palate.</p>`;
 tasteRadar.innerHTML=TASTE_DIMENSIONS.map(tag=>{
   const value=tasteValue(tag);
   return `<div class="taste-axis"><strong>${value>0?"+":""}${value}</strong><small>${titleCase(tag)}</small></div>`
 }).join("");
 tasteNarrative.textContent=preferenceDescription();
 renderPreferenceSliders();

 favouritesList.innerHTML=favourites.length?favourites.map(id=>{const r=RECIPE_LIBRARY.find(x=>x.id===id);return r?`<div class="compact-row"><strong>${escapeHtml(r.name)}</strong><button class="text-btn" onclick="openRecipe('${r.id}')">Open</button></div>`:""}).join(""):`<div class="compact-row">No House Favourites yet.</div>`;

 const filter=historyFilter?.value||"all";
 const visible=history.filter(h=>filter==="all"||h.rating===filter).slice(-12).reverse();
 recentRatings.innerHTML=visible.length?visible.map((h,i)=>{const r=RECIPE_LIBRARY.find(x=>x.id===h.recipeId);const cls=h.rating==="house-favourite"?"favourite":h.rating==="not-for-me"?"negative":"";return `<div class="compact-row" onclick="openHistoryDetail('${h.date}')"><div><strong>${escapeHtml(r?.name||"Cocktail")}</strong><small class="history-badge ${cls}">${titleCase(h.rating.replaceAll("-"," "))}</small>${h.notes?`<div class="history-note">${escapeHtml(h.notes)}</div>`:""}</div><small>${new Date(h.date).toLocaleDateString()}</small></div>`}).join(""):`<div class="compact-row">No cocktail history in this category.</div>`;

 const next=nextTasteExperiment();
 tasteNextTitle.textContent=next?next.name:"Your current bar is fully explored";
 tasteNextReason.textContent=next?`This gives the app useful new information about your response to ${next.tags.slice(0,2).map(titleCase).join(" and ")} flavours.`:"Add new ingredients or expand the recipe library to continue learning.";
}

barPhotos.onchange=async e=>{for(const file of [...e.target.files]){if(photos.length>=8)break;photos.push({file,url:URL.createObjectURL(file)})}e.target.value="";renderPhotos()};
function renderPhotos(){photoCountLabel.textContent=photos.length?`${photos.length} photo${photos.length===1?"":"s"} ready`:"No photos added";analysePhotos.disabled=photos.length===0;photoStrip.innerHTML=photos.map((p,i)=>`<div class="photo-thumb"><img src="${p.url}" alt="Bar photo ${i+1}"><button onclick="removePhoto(${i})">×</button></div>`).join("")}
window.removePhoto=i=>{URL.revokeObjectURL(photos[i].url);photos.splice(i,1);renderPhotos()};
clearPhotos.onclick=()=>{photos.forEach(p=>URL.revokeObjectURL(p.url));photos=[];renderPhotos();scanResultsCard.classList.add("hidden")};
analysePhotos.onclick=async()=>{
 const originalLabel=analysePhotos.textContent;
 analysePhotos.disabled=true;
 clearPhotos.disabled=true;
 analysePhotos.classList.add("is-loading");
 analysePhotos.setAttribute("aria-busy","true");
 scanResultsCard.classList.add("hidden");
 setScanProgress(5,`Preparing ${photos.length} photograph${photos.length===1?"":"s"}…`);
 try{
  const images=[];
  for(let i=0;i<photos.length;i++){
   const progress=10+Math.round(((i+1)/photos.length)*40);
   setScanProgress(progress,`Preparing photo ${i+1} of ${photos.length}…`);
   images.push(await resizeImageForScan(photos[i].file));
  }
  setScanProgress(58,`Sending ${photos.length} photograph${photos.length===1?"":"s"} securely…`);
  const res=await fetch("/.netlify/functions/analyze-bar",{
   method:"POST",
   headers:{"content-type":"application/json"},
   body:JSON.stringify({images})
  });
  setScanProgress(82,"Identifying bottles and merging duplicates…");
  const raw=await res.text();
  if(!res.ok){
   let detail=raw;
   try{const parsed=JSON.parse(raw);detail=parsed.error||parsed.message||raw}catch{}
   if(res.status===404)throw new Error("The AI scanning function is not deployed.");
   if(res.status===503)throw new Error("The OpenAI API key is not available to the scanner.");
   if(res.status===401)throw new Error("OpenAI rejected the API key.");
   if(res.status===413)throw new Error("The photo upload is too large.");
   throw new Error(`Scan failed (${res.status}): ${detail}`);
  }
  const data=JSON.parse(raw);
  candidates=(data.items||[]).map(x=>({
   name:x.name||"",
   brand:x.brand||"",
   type:mapType(x.type),
   status:x.status==="low"?"low":"good",
   confidence:x.confidence??.5
  }));
  if(!candidates.length)throw new Error("No bottles could be identified. Try closer, brighter photographs with labels facing the camera.");
  setScanProgress(100,`Found ${candidates.length} candidate item${candidates.length===1?"":"s"}.`);
  renderCandidates();
  scanResultsCard.classList.remove("hidden");
  scanResultsCard.scrollIntoView({behavior:"smooth",block:"start"});
  showToast("Scan complete. Confirm each item before saving.");
 }catch(err){
  console.error(err);
  candidates=[];
  scanStatus.textContent=err?.message||"The scan could not be completed.";
  showToast("The scan could not be completed.");
 }finally{
  analysePhotos.disabled=photos.length===0;
  clearPhotos.disabled=false;
  analysePhotos.classList.remove("is-loading");
  analysePhotos.removeAttribute("aria-busy");
  analysePhotos.textContent=originalLabel;
  setTimeout(clearScanProgress,900);
 }
};

function resizeImageForScan(file,maxDimension=1600,quality=.78){
 return new Promise((resolve,reject)=>{
  const image=new Image();
  const url=URL.createObjectURL(file);
  image.onload=()=>{
   try{
    const scale=Math.min(1,maxDimension/Math.max(image.naturalWidth,image.naturalHeight));
    const width=Math.max(1,Math.round(image.naturalWidth*scale));
    const height=Math.max(1,Math.round(image.naturalHeight*scale));
    const canvas=document.createElement("canvas");
    canvas.width=width;canvas.height=height;
    const context=canvas.getContext("2d");
    context.drawImage(image,0,0,width,height);
    URL.revokeObjectURL(url);
    resolve(canvas.toDataURL("image/jpeg",quality));
   }catch(error){
    URL.revokeObjectURL(url);reject(error);
   }
  };
  image.onerror=()=>{URL.revokeObjectURL(url);reject(new Error(`Could not read ${file.name}`))};
  image.src=url;
 });
}
function mapType(t=""){const v=t.toLowerCase();if(v.includes("gin"))return"Gin";if(v.includes("tequila"))return"Tequila";if(v.includes("rum"))return"Rum";if(v.includes("scotch"))return"Scotch";if(v.includes("whisky")||v.includes("rye"))return"Canadian whisky";if(v.includes("vodka"))return"Vodka";if(v.includes("vermouth"))return"Vermouth/Fortified wine";if(v.includes("bitter"))return"Bitters";if(v.includes("amaro")||v.includes("aperitivo"))return"Amaro/Aperitivo";if(v.includes("liqueur"))return"Liqueur";return"Other"}
function renderCandidates(){scanResultCount.textContent=candidates.length;scanCandidates.innerHTML=candidates.map((x,i)=>`<div class="candidate-row"><input value="${escapeHtml(x.name)}" oninput="updateCandidate(${i},'name',this.value)" placeholder="Product"><input value="${escapeHtml(x.brand)}" oninput="updateCandidate(${i},'brand',this.value)" placeholder="Brand"><select onchange="updateCandidate(${i},'type',this.value)">${["Gin","Tequila","Rum","Canadian whisky","Scotch","Irish whiskey","Brandy/Cognac","Vodka","Liqueur","Amaro/Aperitivo","Vermouth/Fortified wine","Bitters","Mixer","Fresh ingredient","Other"].map(t=>`<option ${t===x.type?"selected":""}>${t}</option>`).join("")}</select><button class="text-btn" onclick="removeCandidate(${i})">Remove</button></div>`).join("")}
window.updateCandidate=(i,k,v)=>candidates[i][k]=v;window.removeCandidate=i=>{candidates.splice(i,1);renderCandidates()};
addCandidateRow.onclick=()=>{candidates.push({name:"",brand:"",type:"Other",status:"good",confidence:1});renderCandidates()};
saveScanResults.onclick=()=>{const existing=inventory.map(x=>`${x.brand} ${x.name}`.toLowerCase());candidates.filter(x=>x.name.trim()).forEach(x=>{const key=`${x.brand} ${x.name}`.toLowerCase();if(!existing.some(e=>similar(e,key)))inventory.push({id:crypto.randomUUID(),name:x.name.trim(),brand:x.brand.trim(),type:x.type,status:x.status,notes:`AI scan confidence: ${Math.round((x.confidence||0)*100)}%`})});save();showView("inventoryView");scanResultsCard.classList.add("hidden")};
function similar(a,b){const clean=s=>new Set(s.replace(/[^a-z0-9 ]/g,"").split(/\s+/).filter(w=>w.length>2));const A=clean(a),B=clean(b);const overlap=[...A].filter(x=>B.has(x)).length;return overlap>=Math.min(2,A.size,B.size)}

